#[test]
fn test_the_classic_stored_hello() {
    // zlib.compress(b'hello', 0): header, one stored block, Adler-32.
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(iz_zlib(&crate::testport::hex_blob("7801 010500faff 68656c6c6f 062c0215")[..], 0, 16, out, st), iz_ok(), "status");
    crate::testport::assert_cells_hex(out, "68656c6c6f", "hello");
    crate::testport::assert_eq(iz_consumed(st), 16, "consumed");
}
